/*
 * Component registry shared by three places: the Node AI service, the browser tool and
 * the ArkTS app (entry/src/main/ets/model/ComponentModel.ets keeps the same table).
 * Single source of truth so a tree generated by any of them renders and compiles alike.
 */
(function (root, factory) {
  const api = factory();
  if (typeof module !== 'undefined' && module.exports) {
    module.exports = api;
  } else {
    root.ArkUIRegistry = api;
  }
})(typeof globalThis !== 'undefined' ? globalThis : this, function () {
  const CONTAINER_TYPES = ['Row', 'Column', 'Stack', 'Grid', 'Scroll', 'List', 'Tabs'];

  const CATEGORIES = [
    {
      name: '基础组件',
      entries: [
        { type: 'Text', label: '文本' },
        { type: 'Button', label: '按钮' },
        { type: 'Image', label: '图片' },
        { type: 'TextInput', label: '输入框' }
      ]
    },
    {
      name: '布局组件',
      entries: [
        { type: 'Row', label: '横向布局' },
        { type: 'Column', label: '纵向布局' },
        { type: 'Stack', label: '堆叠布局' },
        { type: 'Grid', label: '网格布局' }
      ]
    },
    {
      name: '媒体组件',
      entries: [
        { type: 'Video', label: '视频' },
        { type: 'Web', label: '网页' },
        { type: 'Canvas', label: '画布' }
      ]
    },
    {
      name: '容器组件',
      entries: [
        { type: 'Scroll', label: '滚动容器' },
        { type: 'List', label: '列表容器' },
        { type: 'Tabs', label: '页签容器' }
      ]
    }
  ];

  const DEFAULT_PROPS = {
    Text: { content: '文本', fontSize: '16', color: '#182431', fontWeight: 'Normal' },
    Button: { label: '按钮', fontSize: '16', bgColor: '#0A59F7', onClick: '' },
    Image: { src: 'startIcon', objectFit: 'Cover', onClick: '' },
    TextInput: { placeholder: '请输入内容', text: '', type: 'normal' },
    Row: {},
    Column: {},
    Stack: {},
    Grid: { columnsTemplate: '1fr 1fr' },
    Scroll: {},
    List: {},
    Tabs: { titles: '页签一,页签二', barPosition: 'Start', vertical: 'false' },
    Video: { src: '', autoPlay: 'false' },
    Web: { src: 'https://developer.huawei.com' },
    Canvas: {}
  };

  const DEFAULT_STYLE = {
    width: 120,
    height: 40,
    backgroundColor: '#00000000',
    borderRadius: 0,
    margin: 6,
    padding: 8
  };

  const PROP_SCHEMA = {
    Text: [
      { key: 'content', label: '文本内容', kind: 'text' },
      { key: 'fontSize', label: '字号', kind: 'number' },
      { key: 'color', label: '字体颜色', kind: 'text' },
      { key: 'fontWeight', label: '字重', kind: 'enum', options: ['Lighter', 'Normal', 'Bold', 'Bolder'] }
    ],
    Button: [
      { key: 'label', label: '按钮文字', kind: 'text' },
      { key: 'fontSize', label: '字号', kind: 'number' },
      { key: 'bgColor', label: '按钮颜色', kind: 'text' },
      { key: 'onClick', label: 'onClick 事件', kind: 'event' }
    ],
    Image: [
      { key: 'src', label: '资源名或链接', kind: 'text' },
      { key: 'objectFit', label: '填充方式', kind: 'enum', options: ['Cover', 'Contain', 'Fill', 'None'] },
      { key: 'onClick', label: 'onClick 事件', kind: 'event' }
    ],
    TextInput: [
      { key: 'placeholder', label: '占位文本', kind: 'text' },
      { key: 'text', label: '初始内容', kind: 'text' },
      { key: 'type', label: '输入类型', kind: 'enum', options: ['normal', 'password', 'email', 'number'] }
    ],
    Row: [
      { key: 'justifyContent', label: '主轴对齐', kind: 'enum', options: ['Start', 'Center', 'End', 'SpaceBetween', 'SpaceAround'] },
      { key: 'alignItems', label: '交叉轴对齐', kind: 'enum', options: ['Top', 'Center', 'Bottom'] },
      { key: 'space', label: '子组件间距', kind: 'number' }
    ],
    Column: [
      { key: 'justifyContent', label: '主轴对齐', kind: 'enum', options: ['Start', 'Center', 'End', 'SpaceBetween', 'SpaceAround'] },
      { key: 'alignItems', label: '交叉轴对齐', kind: 'enum', options: ['Top', 'Center', 'Bottom'] },
      { key: 'space', label: '子组件间距', kind: 'number' }
    ],
    Stack: [{ key: 'alignContent', label: '对齐方式', kind: 'enum', options: ['TopStart', 'Center', 'BottomEnd'] }],
    Grid: [{ key: 'columnsTemplate', label: '列模板', kind: 'text' }],
    List: [{ key: 'space', label: '列表间距', kind: 'number' }],
    Scroll: [],
    Tabs: [
      { key: 'titles', label: '页签标题（逗号分隔）', kind: 'text' },
      { key: 'barPosition', label: '页签位置', kind: 'enum', options: ['Start', 'End'] },
      { key: 'vertical', label: '纵向页签', kind: 'enum', options: ['false', 'true'] }
    ],
    Video: [
      { key: 'src', label: '视频地址', kind: 'text' },
      { key: 'autoPlay', label: '自动播放', kind: 'enum', options: ['false', 'true'] }
    ],
    Web: [{ key: 'src', label: '网页地址', kind: 'text' }],
    Canvas: []
  };

  let seed = 0;

  function nextId() {
    seed += 1;
    return `n${Date.now().toString(36)}${seed.toString(36)}`;
  }

  function isContainer(type) {
    return CONTAINER_TYPES.indexOf(type) >= 0;
  }

  function knownType(type) {
    return Object.prototype.hasOwnProperty.call(DEFAULT_PROPS, type);
  }

  function defaultPropsFor(type) {
    return Object.assign({}, DEFAULT_PROPS[type] || {});
  }

  function defaultStyleFor(type) {
    const style = Object.assign({}, DEFAULT_STYLE);
    if (isContainer(type)) {
      style.width = 260;
      style.height = 140;
      style.backgroundColor = '#1A007BFF';
      style.borderRadius = 8;
    } else if (type === 'Image') {
      style.width = 96;
      style.height = 96;
    } else if (type === 'Video' || type === 'Web' || type === 'Canvas') {
      style.width = 220;
      style.height = 130;
      style.backgroundColor = '#11000000';
      style.borderRadius = 6;
    } else if (type === 'TextInput') {
      style.width = 200;
    }
    return style;
  }

  function createNode(type, options) {
    const opts = options || {};
    const safeType = knownType(type) ? type : 'Column';
    const node = {
      id: opts.id || nextId(),
      type: safeType,
      props: Object.assign(defaultPropsFor(safeType), opts.props || {}),
      children: [],
      style: Object.assign(defaultStyleFor(safeType), opts.style || {})
    };
    (opts.children || []).forEach((child) => {
      node.children.push(child.id ? child : createNode(child.type, child));
    });
    return node;
  }

  function labelFor(type) {
    let label = type;
    CATEGORIES.forEach((category) => {
      category.entries.forEach((entry) => {
        if (entry.type === type) {
          label = entry.label;
        }
      });
    });
    return label;
  }

  return {
    CATEGORIES: CATEGORIES,
    PROP_SCHEMA: PROP_SCHEMA,
    DEFAULT_STYLE: DEFAULT_STYLE,
    CONTAINER_TYPES: CONTAINER_TYPES,
    isContainer: isContainer,
    knownType: knownType,
    createNode: createNode,
    labelFor: labelFor,
    nextId: nextId
  };
});
